/** Shared, deterministic selectors. No source observation is generated by the UI. */
export const isTest = (record) => record.kind === 'test record' && !record.duplicateOf;

export function filterInvestigations(investigations, filters) {
  const query = filters.query.trim().toLowerCase();
  return investigations.filter(
    (investigation) =>
      (!query ||
        [
          investigation.name,
          investigation.title,
          investigation.accession,
          investigation.summary,
          ...investigation.keywords,
        ]
          .join(' ')
          .toLowerCase()
          .includes(query)) &&
      (!filters.fuel || investigation.fuelType === filters.fuel) &&
      (!filters.area || investigation.areas.includes(filters.area)) &&
      (!filters.hardware || investigation.hardwareGroup === filters.hardware),
  );
}

export function chartRecords(
  records,
  { accession = '', basis = 'ambient', x = 'oxygen', y = 'pressure' },
) {
  return records.filter(
    (record) =>
      isTest(record) &&
      (!accession || record.accession === accession) &&
      ((x !== 'oxygen' && y !== 'oxygen') || record.oxygenBasis === basis) &&
      Number.isFinite(record[x]?.value) &&
      Number.isFinite(record[y]?.value),
  );
}

export function searchEvidence(dataset, question, limit = 8) {
  const words = question.toLowerCase().match(/[a-z0-9-]{3,}/g) || [];
  const stopWords = new Set([
    'the',
    'and',
    'what',
    'which',
    'with',
    'were',
    'does',
    'that',
    'for',
    'how',
    'did',
    'are',
    'was',
    'tests',
    'test',
  ]);
  const terms = [...new Set(words.filter((word) => !stopWords.has(word)))];
  if (!terms.length) return [];
  const tableMap = new Map(dataset.tables.map((table) => [table.id, table]));
  const invMap = new Map(
    dataset.investigations.map((investigation) => [investigation.accession, investigation]),
  );
  return dataset.records
    .filter(
      (record) =>
        !record.duplicateOf && !['continuation / note', 'note / calibration'].includes(record.kind),
    )
    .map((record) => {
      const inv = invMap.get(record.accession);
      const ownText = [
        record.label,
        record.accession,
        record.fuel,
        record.outcome,
        ...record.values,
      ]
        .join(' ')
        .toLowerCase();
      const context = [inv.name, inv.summary, inv.safetyArea].join(' ').toLowerCase();
      const score = terms.reduce(
        (sum, term) => sum + (ownText.includes(term) ? 3 : context.includes(term) ? 1 : 0),
        0,
      );
      return { ...record, score, investigation: inv.name, file: tableMap.get(record.tableId).file };
    })
    .filter((record) => record.score > 0)
    .sort((a, b) => b.score - a.score || a.id.localeCompare(b.id))
    .slice(0, limit);
}

export function rangeLabel(range, unit = '') {
  if (!range) return 'Not reported';
  const format = (number) => Number(number.toFixed(2)).toLocaleString('en');
  return `${format(range.min)}${range.min === range.max ? '' : `–${format(range.max)}`} ${unit}`.trim();
}

export function csvText(headers, rows) {
  // Neutralize formula injection when opening exported text in a spreadsheet.
  const escape = (value) => {
    const text = String(value ?? '');
    const safe = /^[=+@\-\t\r]/.test(text) ? `'${text}` : text;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [headers, ...rows].map((row) => row.map(escape).join(',')).join('\r\n');
}
